import csv, collections, json

d=collections.defaultdict(dict)
for r in csv.DictReader(open("data.csv")):
    d[r["band"]][r["month"]]=float(r["mean_value"])
months=sorted(next(iter(d.values())).keys())
series={b:[v[m] for m in months] for b,v in d.items()}

def simplex_fit(targets, donors, iters=4000, step=0.05):
    k=len(donors); n=len(targets)
    w=[1.0/k]*k
    def loss(w):
        return sum((sum(wi*di[j] for wi,di in zip(w,donors))-targets[j])**2 for j in range(n))
    for it in range(iters):
        grad=[]
        for i in range(k):
            di=donors[i]
            g=0.0
            for j in range(n):
                r=sum(wi*dj[j] for wi,dj in zip(w,donors))-targets[j]
                g+=2*r*di[j]
            grad.append(g)
        w=[max(0.0,wi-step*gi) for wi,gi in zip(w,grad)]
        s=sum(w)
        if s>0: w=[wi/s for wi in w]
    return w, loss(w)

preds={}; diag={}
for b,ys in series.items():
    N=len(ys)
    best=None
    for m in range(2,5):
        treated=ys[N-m:]
        donors=[]; posts=[]
        for i in range(m-1, N-m-1):
            donors.append(ys[i-m+1:i+1]); posts.append(ys[i+1])
        if not donors: continue
        w,mse=simplex_fit(treated,donors)
        mu=sum(ys)/N; sd=(sum((y-mu)**2 for y in ys)/N)**0.5 or 1
        smse=mse/(m*sd*sd)
        if best is None or smse<best[0]: best=(smse,m,w,posts)
    smse,m,w,posts=best
    pred=sum(wi*p for wi,p in zip(w,posts))
    preds[b]=pred; diag[b]={"m":m,"std_matching_mse":round(smse,4),"weights":[round(x,3) for x in w]}
    print(b, "m=",m, "smse=",round(smse,4), "pred=",round(pred,4))

json.dump({"prediction":preds,
